#!/usr/bin/env python3
"""Inventory Pi deployment destinations and stage reviewed files without installing."""
import base64, hashlib, json, os, platform, shutil, subprocess, sys, tarfile, tempfile, zlib
from pathlib import Path
PAYLOAD = ''
PAYLOAD_SHA = '29540cc8eb4d870faab3af30d257c54163b08d52dae41a08b78a1c91bd5ecd06'

def engine():
    raw=zlib.decompress(base64.b64decode(PAYLOAD, validate=True))
    if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA: raise RuntimeError('Embedded helper hash mismatch')
    scope={'__name__':'reviewed_trial_engine','__file__':__file__}
    exec(compile(raw,'reviewed_trial_engine','exec'),scope)
    return scope

def snapshot(root, inventory):
    if root.is_symlink(): raise RuntimeError('Destination root is a symlink: '+str(root))
    if not root.exists(): return {'exists':False}
    rows=inventory(root)
    return {'exists':True,'entries':len(rows),'inventory_sha256':hashlib.sha256(json.dumps(rows,sort_keys=True).encode()).hexdigest()}

def prepare(work, state, home, e):
    source=e['locate_profile'](state)
    roots=sorted(p.name for p in source.iterdir())
    if any(not p.is_dir() or p.is_symlink() for p in source.iterdir()): raise RuntimeError('Unexpected profile root')
    target=home/'.config'
    if target.is_symlink(): raise RuntimeError('Config directory is a symlink')
    before={name:snapshot(target/name,e['inventory']) for name in roots}
    (work/'destination-snapshots.json').write_text(json.dumps(before,indent=2)+'\n')
    staged=work/'candidate-home'; staged.mkdir()
    shutil.copytree(source,staged/'.config',symlinks=True)
    report={'status':'PREPARED','certification':'NOT_CERTIFIED','live_configuration':'NOT_REPLACED','destinations':before}
    e['repair_wallpaper'](staged,report)
    # Every symlink must remain within the staged configuration tree.
    config=staged/'.config'
    for p in config.rglob('*'):
        if p.is_symlink() and (not p.exists() or not p.resolve().is_relative_to(config.resolve())):
            raise RuntimeError('Escaping or dangling staged link')
    records=e['inventory'](config)
    (work/'candidate-manifest.json').write_text(json.dumps(records,indent=2)+'\n')
    report['candidate_manifest_sha256']=e['sha'](work/'candidate-manifest.json')
    report['candidate_home']=str(staged)
    after={name:snapshot(target/name,e['inventory']) for name in roots}
    if before!=after: raise RuntimeError('Destination changed during preparation')
    report['destination_snapshots_unchanged']=True
    return report

def main():
    if platform.machine() not in ('aarch64','arm64') or os.geteuid()==0:
        print('Run as the normal user on the Pi.',file=sys.stderr);return 20
    if os.environ.get('XDG_CONFIG_HOME',str(Path.home()/'.config'))!=str(Path.home()/'.config'):
        print('Custom XDG_CONFIG_HOME needs explicit reconciliation.',file=sys.stderr);return 20
    os.umask(0o077)
    state=Path.home()/'.local/state/gup-r7'
    if not state.is_dir() or state.is_symlink(): raise RuntimeError('Existing GUP state missing')
    work=Path(tempfile.mkdtemp(prefix='deployment-preflight-',dir=state))
    report={'status':'BLOCKED','live_configuration':'NOT_REPLACED','certification':'NOT_CERTIFIED'}
    code=0
    try:
        report=prepare(work,state,Path.home(),engine())
        print('Prepared private candidate; all deployment destinations recorded.')
    except Exception as error:
        report.update(status='BLOCKED',error=str(error));code=1
    report['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    (work/'report.json').write_text(json.dumps(report,indent=2)+'\n')
    files=[p for p in work.iterdir() if p.is_file()]
    (work/'SHA256SUMS').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.name+'\n' for p in sorted(files)))
    archive=work.with_suffix('.tar.gz')
    with tarfile.open(archive,'w:gz') as t:
        for p in sorted(work.iterdir()):
            if p.is_file():t.add(p,arcname=p.name)
    print(archive);print(hashlib.sha256(archive.read_bytes()).hexdigest())
    print('Return this archive and SHA256. No live configuration was replaced.')
    return code
if __name__=='__main__':sys.exit(main())
